    const extent = resolveDataXExtent(data, xAccessor);
    if (!extent) {
        return null;
    }
    if (!xExtentMax || xExtentMax.getTime() <= extent[1].getTime()) {
        return extent;
    }
    return [extent[0], xExtentMax];
}

